using System.Diagnostics;
namespace SoloCamera.Windows;
public static class UsbForward {
 public static void Remove(int port){try{string adb=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Android","Sdk","platform-tools","adb.exe");var info=new ProcessStartInfo(adb){UseShellExecute=false,CreateNoWindow=true};info.ArgumentList.Add("forward");info.ArgumentList.Add("--remove");info.ArgumentList.Add("tcp:"+port);using var process=Process.Start(info);if(process!=null&&!process.WaitForExit(2000))process.Kill();}catch{}}
 public static (string Host,int Port) Open(int phonePort){string adb=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Android","Sdk","platform-tools","adb.exe");if(!File.Exists(adb))throw new IOException("USB needs Android platform-tools (adb). Install platform-tools or use Wi-Fi/hotspot pairing.");
 string Run(params string[] args){var info=new ProcessStartInfo(adb){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(string arg in args)info.ArgumentList.Add(arg);using var process=Process.Start(info)??throw new IOException("Cannot start USB bridge");var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(7000)){process.Kill();throw new IOException("USB bridge timed out");}if(process.ExitCode!=0)throw new IOException(error.GetAwaiter().GetResult());return output.GetAwaiter().GetResult().Trim();}
 var devices=Run("devices").Split('\n').Where(x=>x.TrimEnd().EndsWith("\tdevice",StringComparison.Ordinal)).Select(x=>x.Split('\t')[0]).ToArray();if(devices.Length!=1)throw new IOException("Connect one unlocked USB phone and approve USB debugging on it, or use Wi-Fi/hotspot.");if(!int.TryParse(Run("-s",devices[0],"forward","tcp:0","tcp:"+phonePort),out int port)||port<1)throw new IOException("USB port forwarding failed");return("127.0.0.1",port);
 }
}
